screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス
  const deliveryTableIndex = 1; // 納期実績テーブル
  const orderTableIndex = 0; // 発注履歴テーブル
  const materialTableIndex = 2; // 資材マスタテーブル
  const supplierTableIndex = 4; // 発注先マスタテーブル
  const scheduleTableIndex = 5; // 工程スケジュールテーブル
  const priorityTableIndex = 8; // 発注優先順位テーブル

  // 再描画関数の定義
  function renderDeliveryRows(rows) {
    const tbody = container.querySelector("#delivery-performance-tbody");
    tbody.innerHTML = rows.map(row => {
      const delayDays = row.納期遅延日数 || 0;
      const delayClass = delayDays > 0 ? 'style="color: #ef4444;"' : delayDays < 0 ? 'style="color: #22c55e;"' : '';
      const statusBadge = getStatusBadge(row.納品ステータス);

      return `
        <tr data-id="${row.納期実績ID}" style="cursor: pointer;">
          <td style="padding: 8px 6px; font-size: 12px;">${row.発注番号 || ''}</td>
          <td style="padding: 8px 6px; font-size: 12px;">${row.資材名 || ''}</td>
          <td style="padding: 8px 6px; font-size: 12px;">${row.発注先名 || ''}</td>
          <td style="padding: 8px 6px; font-size: 12px;">${formatDate(row.納期予定日)}</td>
          <td style="padding: 8px 6px; font-size: 12px;">${formatDate(row.納期実績日)}</td>
          <td style="padding: 8px 6px; font-size: 12px;" ${delayClass}>${delayDays}日</td>
          <td style="padding: 8px 6px; font-size: 12px;">${statusBadge}</td>
          <td style="padding: 8px 6px; font-size: 12px;">
            <button class="action-btn secondary detail-btn" data-id="${row.納期実績ID}" style="padding: 2px 6px; font-size: 11px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  function getStatusBadge(status) {
    const badges = {
      '発注中': '<span style="background: #f59e0b; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px;">発注中</span>',
      '一部納品': '<span style="background: #3b82f6; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px;">一部納品</span>',
      '完納': '<span style="background: #22c55e; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px;">完納</span>',
      '遅延': '<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 10px;">遅延</span>'
    };
    return badges[status] || status;
  }

  function formatDate(dateStr) {
    if (!dateStr) return '-';
    const date = new Date(dateStr);
    return `${date.getMonth() + 1}/${date.getDate()}`;
  }

  // KPI更新関数
  function updateKPIs(deliveryData) {
    const totalOrders = deliveryData.length;
    const onTimeOrders = deliveryData.filter(d => (d.納期遅延日数 || 0) <= 0).length;
    const onTimeRate = totalOrders > 0 ? Math.round((onTimeOrders / totalOrders) * 100) : 0;
    const delays = deliveryData.filter(d => (d.納期遅延日数 || 0) > 0);
    const avgDelay = delays.length > 0 ? Math.round(delays.reduce((sum, d) => sum + (d.納期遅延日数 || 0), 0) / delays.length) : 0;
    const riskAlerts = deliveryData.filter(d => (d.納期遅延日数 || 0) > 7).length;

    container.querySelector("#kpi-total-orders").textContent = totalOrders;
    container.querySelector("#kpi-on-time-rate").textContent = `${onTimeRate}%`;
    container.querySelector("#kpi-avg-delay").textContent = `${avgDelay}日`;
    container.querySelector("#kpi-risk-alerts").textContent = riskAlerts;
  }

  // 発注先別サマリー更新
  function updateSupplierSummary(deliveryData) {
    const supplierStats = {};
    deliveryData.forEach(d => {
      const supplier = d.発注先名 || '不明';
      if (!supplierStats[supplier]) {
        supplierStats[supplier] = { total: 0, onTime: 0 };
      }
      supplierStats[supplier].total++;
      if ((d.納期遅延日数 || 0) <= 0) {
        supplierStats[supplier].onTime++;
      }
    });

    const summaryHtml = Object.entries(supplierStats).map(([supplier, stats]) => {
      const rate = Math.round((stats.onTime / stats.total) * 100);
      const rateColor = rate >= 90 ? '#22c55e' : rate >= 70 ? '#f59e0b' : '#ef4444';
      return `
        <div style="display: flex; justify-content: space-between; align-items: center; padding: 4px 0; border-bottom: 1px solid var(--border);">
          <span style="font-size: 11px; color: var(--text);">${supplier}</span>
          <span style="font-size: 11px; color: ${rateColor}; font-weight: 600;">${rate}%</span>
        </div>
      `;
    }).join("");

    container.querySelector("#supplier-summary").innerHTML = summaryHtml;
  }

  // 工程スケジュールサマリー更新
  function updateScheduleSummary() {
    window.aivicApi.list(scheduleTableIndex).then(schedules => {
      if (!schedules) return;

      const recentSchedules = schedules.slice(0, 3);
      const summaryHtml = recentSchedules.map(schedule => {
        const statusColor = schedule.工程ステータス === '遅延' ? '#ef4444' : 
                           schedule.工程ステータス === '完了' ? '#22c55e' : '#f59e0b';
        return `
          <div style="display: flex; justify-content: space-between; align-items: center; padding: 3px 0;">
            <span style="font-size: 11px; color: var(--text);">${schedule.工程名 || ''}</span>
            <span style="font-size: 10px; color: ${statusColor};">${schedule.工程ステータス || ''}</span>
          </div>
        `;
      }).join("");

      container.querySelector("#schedule-summary").innerHTML = summaryHtml;
    });
  }

  // 初期データ読み込みと描画
  window.aivicApi.list(deliveryTableIndex).then(deliveryData => {
    if (deliveryData) {
      renderDeliveryRows(deliveryData);
      updateKPIs(deliveryData);
      updateSupplierSummary(deliveryData);
    }
  });

  updateScheduleSummary();

  // 検索機能
  container.querySelector("#btn-search").addEventListener("click", () => {
    const supplierFilter = container.querySelector("#filter-supplier").value;
    const statusFilter = container.querySelector("#filter-status").value;
    const dateFrom = container.querySelector("#filter-date-from").value;

    window.aivicApi.list(deliveryTableIndex).then(rows => {
      if (!rows) return;

      let filtered = rows.filter(row => {
        if (supplierFilter && row.発注先名 !== supplierFilter) return false;
        if (statusFilter && row.納品ステータス !== statusFilter) return false;
        if (dateFrom && row.納期予定日 && new Date(row.納期予定日) < new Date(dateFrom)) return false;
        return true;
      });

      renderDeliveryRows(filtered);
      updateKPIs(filtered);
      updateSupplierSummary(filtered);
    });
  });

  // CSVエクスポート
  container.querySelector("#btn-export-csv").addEventListener("click", () => {
    window.aivicApi.list(deliveryTableIndex).then(rows => {
      if (!rows) return;

      const headers = ['発注番号', '資材名', '発注先名', '納期予定日', '納期実績日', '遅延日数', '納品ステータス'];
      const csvContent = '\uFEFF' + [
        headers.join(','),
        ...rows.map(row => [
          row.発注番号 || '',
          row.資材名 || '',
          row.発注先名 || '',
          row.納期予定日 || '',
          row.納期実績日 || '',
          row.納期遅延日数 || 0,
          row.納品ステータス || ''
        ].map(field => `"${field}"`).join(','))
      ].join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = '納期実績_' + new Date().toISOString().split('T')[0] + '.csv';
      link.click();
    });
  });

  // 優先順位更新
  container.querySelector("#btn-update-priority").addEventListener("click", () => {
    const material = container.querySelector("#priority-material").value;
    const level = container.querySelector("#priority-level").value;

    if (!material || !level) {
      alert('資材と優先度を選択してください');
      return;
    }

    const priorityData = {
      プロジェクトID: 'proj-001',
      資材ID: material,
      工程ID: 'process-001',
      優先度: parseInt(level),
      必要納期: new Date(Date.now() + 30 * 24 * 60 * 60 * 1000).toISOString(),
      推奨発注日: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      リスクレベル: level <= 2 ? '高' : level <= 3 ? '中' : '低',
      発注状況: '未発注',
      数量: 100,
      有効フラグ: true,
      作成者: 'user-001',
      更新者: 'user-001'
    };

    window.aivicApi.save(priorityTableIndex, priorityData).then(result => {
      if (result) {
        alert('優先順位を更新しました');
        container.querySelector("#priority-material").value = '';
        container.querySelector("#priority-level").value = '';
      }
    });
  });

  // イベントデリゲーション（詳細表示）
  container.addEventListener("click", (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.aivicApi.list(deliveryTableIndex).then(rows => {
        if (!rows) return;

        const record = rows.find(r => r.納期実績ID === id);
        if (record) {
          showDelayDetail(record);
        }
      });
    }

    const closeBtn = e.target.closest("#btn-close-modal");
    if (closeBtn) {
      container.querySelector("#delay-detail-modal").style.display = "none";
    }
  });

  // 遅延詳細表示
  function showDelayDetail(record) {
    const content = `
      <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 12px; font-size: 12px;">
        <div><strong>発注番号:</strong> ${record.発注番号 || ''}</div>
        <div><strong>資材名:</strong> ${record.資材名 || ''}</div>
        <div><strong>発注先:</strong> ${record.発注先名 || ''}</div>
        <div><strong>発注数量:</strong> ${record.発注数量 || 0}</div>
        <div><strong>納期予定:</strong> ${formatDate(record.納期予定日)}</div>
        <div><strong>納期実績:</strong> ${formatDate(record.納期実績日)}</div>
        <div><strong>遅延日数:</strong> <span style="color: ${(record.納期遅延日数 || 0) > 0 ? '#ef4444' : '#22c55e'};">${record.納期遅延日数 || 0}日</span></div>
        <div><strong>納品数量:</strong> ${record.納品数量 || 0}</div>
      </div>
      <div style="margin-top: 12px;">
        <strong>備考:</strong>
        <div style="background: var(--bg-main); padding: 8px; border-radius: 4px; margin-top: 4px; font-size: 11px;">
          ${record.備考 || '特記事項なし'}
        </div>
      </div>
    `;

    container.querySelector("#delay-detail-content").innerHTML = content;
    container.querySelector("#delay-detail-modal").style.display = "block";
  }
}

function(container, apiUrl, tables) {
  // チャート描画関数
  function drawPerformanceChart() {
    const canvas = container.querySelector('#performance-chart');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const width = canvas.width;
    const height = canvas.height;

    // 背景をクリア
    ctx.clearRect(0, 0, width, height);

    // データ（月別納期遵守率）
    const months = ['1月', '2月', '3月', '4月', '5月', '6月'];
    const rates = [85, 88, 82, 90, 87, 89];

    // グリッド描画
    ctx.strokeStyle = '#374151';
    ctx.lineWidth = 1;

    // 横線
    for (let i = 0; i <= 5; i++) {
      const y = 40 + (height - 80) * i / 5;
      ctx.beginPath();
      ctx.moveTo(60, y);
      ctx.lineTo(width - 20, y);
      ctx.stroke();
    }

    // 縦線
    for (let i = 0; i <= 5; i++) {
      const x = 60 + (width - 80) * i / 5;
      ctx.beginPath();
      ctx.moveTo(x, 40);
      ctx.lineTo(x, height - 40);
      ctx.stroke();
    }

    // Y軸ラベル
    ctx.fillStyle = '#9ca3af';
    ctx.font = '12px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 5; i++) {
      const y = 40 + (height - 80) * i / 5;
      const value = 100 - i * 4;
      ctx.fillText(value + '%', 55, y + 4);
    }

    // X軸ラベル
    ctx.textAlign = 'center';
    for (let i = 0; i < months.length; i++) {
      const x = 60 + (width - 80) * i / 5;
      ctx.fillText(months[i], x, height - 20);
    }

    // 線グラフ描画
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 3;
    ctx.beginPath();

    for (let i = 0; i < rates.length; i++) {
      const x = 60 + (width - 80) * i / 5;
      const y = 40 + (height - 80) * (100 - rates[i]) / 20;

      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }

      // データポイント
      ctx.fillStyle = '#3b82f6';
      ctx.beginPath();
      ctx.arc(x, y, 4, 0, 2 * Math.PI);
      ctx.fill();
    }
    ctx.stroke();
  }

  // KPI更新関数
  function updateKPIs(data) {
    if (!data || data.length === 0) return;

    // 納期パフォーマンス指標から集計
    const performanceData = data.filter(item => item.tableName === '納期パフォーマンス指標');
    if (performanceData.length > 0) {
      const records = performanceData[0].records || [];

      if (records.length > 0) {
        const avgCompliance = records.reduce((sum, r) => sum + (r.納期遵守率 || 0), 0) / records.length;
        const avgDelay = records.reduce((sum, r) => sum + (r.平均遅延日数 || 0), 0) / records.length;
        const totalOrders = records.reduce((sum, r) => sum + (r.総発注件数 || 0), 0);
        const highRisk = records.filter(r => r.評価ランク === 'C' || r.評価ランク === 'D').length;

        const complianceEl = container.querySelector('#kpi-compliance');
        const delayEl = container.querySelector('#kpi-delay');
        const ordersEl = container.querySelector('#kpi-orders');
        const riskEl = container.querySelector('#kpi-risk');

        if (complianceEl) complianceEl.textContent = avgCompliance.toFixed(1) + '%';
        if (delayEl) delayEl.textContent = avgDelay.toFixed(1) + '日';
        if (ordersEl) ordersEl.textContent = totalOrders.toLocaleString() + '件';
        if (riskEl) riskEl.textContent = highRisk + '社';
      }
    }
  }

  // 分析実行
  function executeAnalysis() {
    const supplierId = container.querySelector('#supplier-filter').value;
    const startDate = container.querySelector('#period-start').value;
    const endDate = container.querySelector('#period-end').value;

    // 納期パフォーマンス指標を取得
    window.aivicApi.list(7).then(data => {
      if (data) {
        let filteredData = data;

        // フィルタリング
        if (supplierId) {
          filteredData = filteredData.filter(item => item.発注先ID === supplierId);
        }

        if (startDate && endDate) {
          filteredData = filteredData.filter(item => {
            const itemDate = new Date(item.集計期間開始日);
            return itemDate >= new Date(startDate) && itemDate <= new Date(endDate);
          });
        }

        updateKPIs([{ tableName: '納期パフォーマンス指標', records: filteredData }]);
        drawPerformanceChart();
      }
    });
  }

  // CSVエクスポート
  function exportCSV() {
    window.aivicApi.list(7).then(data => {
      if (!data) return;

      const headers = ['発注先ID', '資材ID', '集計期間開始日', '集計期間終了日', '総発注件数', '納期遵守件数', '納期遵守率', '平均遅延日数', '最大遅延日数', '評価ランク'];
      const csvContent = '\uFEFF' + headers.join(',') + '\n' + 
        data.map(row => headers.map(header => {
          const value = row[header] || '';
          return typeof value === 'string' && value.includes(',') ? `"${value}"` : value;
        }).join(',')).join('\n');

      const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
      const link = document.createElement('a');
      link.href = URL.createObjectURL(blob);
      link.download = 'supplier_performance_analysis.csv';
      link.click();
    });
  }

  // イベントリスナー設定
  const analyzeBtn = container.querySelector('#btn-analyze');
  if (analyzeBtn) {
    analyzeBtn.addEventListener('click', executeAnalysis);
  }

  const exportBtn = container.querySelector('#btn-export');
  if (exportBtn) {
    exportBtn.addEventListener('click', exportCSV);
  }

  // 初期化
  updateKPIs(tables);
  drawPerformanceChart();

  // 初期分析実行
  executeAnalysis();
}

function(container, apiUrl, tables) {
  // テーブルインデックス定義
  const scheduleTableIndex = tables.findIndex(t => t.tableName === '工程スケジュール');
  const priorityTableIndex = tables.findIndex(t => t.tableName === '発注優先順位');
  const orderHistoryTableIndex = tables.findIndex(t => t.tableName === '発注履歴');
  const performanceTableIndex = tables.findIndex(t => t.tableName === '納期パフォーマンス指標');
  const riskTableIndex = tables.findIndex(t => t.tableName === 'リスク評価結果');

  // 工程スケジュール再描画関数
  function renderSchedule(rows) {
    const tbody = container.querySelector('#schedule-tbody');
    tbody.innerHTML = rows.map(r => {
      const progressWidth = r.進捗率 || 0;
      const statusColor = r.工程ステータス === '完了' ? '#27ae60' : 
                         r.工程ステータス === '遅延' ? '#e74c3c' : 
                         r.工程ステータス === '進行中' ? '#3498db' : '#95a5a6';

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 8px 12px; color: var(--text);">${r.工程名 || ''}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 12px;">
            ${r.予定開始日 ? new Date(r.予定開始日).toLocaleDateString() : ''} - 
            ${r.予定完了日 ? new Date(r.予定完了日).toLocaleDateString() : ''}
          </td>
          <td style="padding: 8px 12px;">
            <div style="display: flex; align-items: center; gap: 8px;">
              <div style="width: 60px; height: 4px; background: rgba(255,255,255,0.1); border-radius: 2px; position: relative;">
                <div style="width: ${progressWidth}%; height: 100%; background: var(--primary); border-radius: 2px;"></div>
              </div>
              <span style="font-size: 12px; color: var(--text);">${progressWidth}%</span>
            </div>
          </td>
          <td style="padding: 8px 12px;">
            <span style="padding: 2px 6px; border-radius: 12px; font-size: 11px; background: ${statusColor}20; color: ${statusColor};">
              ${r.工程ステータス || ''}
            </span>
          </td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 12px;">${r.責任者名 || ''}</td>
        </tr>
      `;
    }).join('');
  }

  // 発注優先順位再描画関数
  function renderPriority(rows) {
    const tbody = container.querySelector('#priority-tbody');
    tbody.innerHTML = rows.map(r => {
      const riskColor = r.リスクレベル === '高' ? '#e74c3c' : 
                       r.リスクレベル === '中' ? '#ff6a00' : '#27ae60';
      const statusColor = r.発注状況 === '未発注' ? '#e74c3c' : 
                         r.発注状況 === '発注済' ? '#3498db' : '#27ae60';

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border);">
          <td style="padding: 8px 12px;">
            <span style="display: inline-block; width: 20px; height: 20px; border-radius: 50%; background: var(--primary); color: #fff; text-align: center; line-height: 20px; font-size: 11px; font-weight: 600;">
              ${r.優先度 || ''}
            </span>
          </td>
          <td style="padding: 8px 12px; color: var(--text);">${r.資材名 || ''}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 12px;">
            ${r.必要納期 ? new Date(r.必要納期).toLocaleDateString() : ''}
          </td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 12px;">
            ${r.推奨発注日 ? new Date(r.推奨発注日).toLocaleDateString() : ''}
          </td>
          <td style="padding: 8px 12px;">
            <span style="padding: 2px 6px; border-radius: 12px; font-size: 11px; background: ${riskColor}20; color: ${riskColor};">
              ${r.リスクレベル || ''}
            </span>
          </td>
          <td style="padding: 8px 12px;">
            <span style="padding: 2px 6px; border-radius: 12px; font-size: 11px; background: ${statusColor}20; color: ${statusColor};">
              ${r.発注状況 || ''}
            </span>
          </td>
          <td style="padding: 8px 12px;">
            <button class="action-btn secondary order-btn" data-id="${r.id}" style="font-size: 11px; padding: 2px 6px;">
              発注
            </button>
          </td>
        </tr>
      `;
    }).join('');
  }

  // 資材発注状況再描画関数
  function renderOrderStatus(rows) {
    const tbody = container.querySelector('#order-status-tbody');
    const recentOrders = rows.slice(0, 8); // 最新8件のみ表示
    tbody.innerHTML = recentOrders.map(r => {
      const statusColor = r.発注ステータス === '入荷済み' ? '#27ae60' : 
                         r.発注ステータス === '発注済み' ? '#3498db' : '#95a5a6';

      return `
        <tr style="border-bottom: 1px solid var(--border);">
          <td style="padding: 6px 8px; color: var(--text); font-size: 11px;">${r.商品名 || ''}</td>
          <td style="padding: 6px 8px;">
            <span style="padding: 1px 4px; border-radius: 8px; font-size: 10px; background: ${statusColor}20; color: ${statusColor};">
              ${r.発注ステータス || ''}
            </span>
          </td>
          <td style="padding: 6px 8px; color: var(--text-muted); font-size: 10px;">
            ${r.納期予定日 ? new Date(r.納期予定日).toLocaleDateString() : ''}
          </td>
        </tr>
      `;
    }).join('');
  }

  // 納期実績グラフ描画
  function drawDeliveryChart() {
    const canvas = container.querySelector('#delivery-chart');
    const ctx = canvas.getContext('2d');

    // Canvas サイズ設定
    canvas.width = 800;
    canvas.height = 200;

    // 背景クリア
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // サンプルデータ（過去12週間の納期遵守率）
    const weeks = ['W1', 'W2', 'W3', 'W4', 'W5', 'W6', 'W7', 'W8', 'W9', 'W10', 'W11', 'W12'];
    const rates = [85, 88, 82, 90, 87, 85, 89, 91, 86, 88, 87, 89];

    const padding = 40;
    const chartWidth = canvas.width - padding * 2;
    const chartHeight = canvas.height - padding * 2;
    const stepX = chartWidth / (weeks.length - 1);

    // グリッド線
    ctx.strokeStyle = '#3a4a5c';
    ctx.lineWidth = 1;
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // Y軸ラベル
    ctx.fillStyle = '#9fb0d1';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'right';
    for (let i = 0; i <= 4; i++) {
      const y = padding + (chartHeight / 4) * i;
      const value = 100 - (i * 5);
      ctx.fillText(value + '%', padding - 8, y + 3);
    }

    // X軸ラベル
    ctx.textAlign = 'center';
    weeks.forEach((week, i) => {
      const x = padding + stepX * i;
      ctx.fillText(week, x, canvas.height - 10);
    });

    // 折れ線グラフ
    ctx.strokeStyle = '#3b82f6';
    ctx.lineWidth = 2;
    ctx.beginPath();
    rates.forEach((rate, i) => {
      const x = padding + stepX * i;
      const y = padding + chartHeight - (chartHeight * (rate - 80) / 20);
      if (i === 0) {
        ctx.moveTo(x, y);
      } else {
        ctx.lineTo(x, y);
      }
    });
    ctx.stroke();

    // データポイント
    ctx.fillStyle = '#3b82f6';
    rates.forEach((rate, i) => {
      const x = padding + stepX * i;
      const y = padding + chartHeight - (chartHeight * (rate - 80) / 20);
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();
    });
  }

  // 初期データ読み込み
  if (scheduleTableIndex >= 0) {
    window.aivicApi.list(scheduleTableIndex).then(rows => {
      if (rows) renderSchedule(rows);
    });
  }

  if (priorityTableIndex >= 0) {
    window.aivicApi.list(priorityTableIndex).then(rows => {
      if (rows) renderPriority(rows);
    });
  }

  if (orderHistoryTableIndex >= 0) {
    window.aivicApi.list(orderHistoryTableIndex).then(rows => {
      if (rows) renderOrderStatus(rows);
    });
  }

  // グラフ描画
  setTimeout(drawDeliveryChart, 100);

  // スケジュール更新ボタン
  container.querySelector('#btn-schedule-update').addEventListener('click', async () => {
    if (scheduleTableIndex >= 0) {
      const rows = await window.aivicApi.list(scheduleTableIndex);
      if (rows) renderSchedule(rows);
    }
    alert('スケジュールを更新しました');
  });

  // 発注計画調整ボタン
  container.querySelector('#btn-order-adjust').addEventListener('click', () => {
    window.showScreen('scr-1780996536358');
  });

  // プロジェクト選択変更
  container.querySelector('#project-select').addEventListener('change', async (e) => {
    const projectId = e.target.value;
    if (projectId && scheduleTableIndex >= 0) {
      const rows = await window.aivicApi.list(scheduleTableIndex);
      if (rows) {
        // プロジェクトIDでフィルタリング（実際の実装では必要）
        renderSchedule(rows);
      }
    }
  });

  // 発注ボタンのイベントデリゲーション
  container.addEventListener('click', async (e) => {
    const orderBtn = e.target.closest('.order-btn');
    if (orderBtn) {
      const id = orderBtn.dataset.id;
      if (confirm('この資材を発注しますか？')) {
        // 発注状況を更新
