          await window.aivicApi.update(priorityTableIndex, id, { 発注状況: '発注済' });
          const rows = await window.aivicApi.list(priorityTableIndex);
          if (rows) renderPriority(rows);
        }
      }
    }
  });
}

function(container, apiUrl, tables) {
  // 1. 再描画関数の定義
  function renderRiskRows(rows) {
    const tbody = container.querySelector("#risk-tbody");
    tbody.innerHTML = rows.map(r => `
      <tr data-id="${r.リスク評価ID || r.id}">
        <td>${r.工程名 || "基礎工事"}</td>
        <td>
          <span style="background: ${getRiskColor(r.リスクレベル || 15)}; color: #fff; padding: 2px 8px; border-radius: 12px; font-size: 11px;">
            ${getRiskLabel(r.リスクレベル || 15)}
          </span>
        </td>
        <td>${r.予想遅延日数 || 0}日</td>
        <td>${r.対策実施状況 || "未実施"}</td>
        <td>${r.評価日 ? new Date(r.評価日).toLocaleDateString() : new Date().toLocaleDateString()}</td>
        <td>
          <button class="action-btn secondary detail-btn" data-id="${r.リスク評価ID || r.id}">詳細</button>
          <button class="action-btn secondary edit-btn" data-id="${r.リスク評価ID || r.id}">編集</button>
        </td>
      </tr>
    `).join("");
  }

  function getRiskColor(level) {
    if (level >= 15) return "#ff6b6b";
    if (level >= 8) return "#ffa726";
    return "#66bb6a";
  }

  function getRiskLabel(level) {
    if (level >= 15) return "高";
    if (level >= 8) return "中";
    return "低";
  }

  // 2. 初期データ描画
  const initialData = tables.find(t => t.tableName === "リスク評価結果")?.records || [];
  renderRiskRows(initialData);

  // 3. フィルター機能
  container.querySelector("#risk-level-filter").addEventListener("change", async (e) => {
    const filterValue = e.target.value;
    const allRows = await window.aivicApi.list(7); // リスク評価結果テーブル
    if (!allRows) return;

    let filteredRows = allRows;
    if (filterValue) {
      filteredRows = allRows.filter(r => getRiskLabel(r.リスクレベル || 15) === filterValue);
    }
    renderRiskRows(filteredRows);
  });

  // 4. 更新ボタン
  container.querySelector("#btn-refresh").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(7);
    if (rows) renderRiskRows(rows);
  });

  // 5. リスク評価更新ボタン
  container.querySelector("#btn-update-evaluation").addEventListener("click", async () => {
    // リスク評価の再計算処理
    const rows = await window.aivicApi.list(7);
    if (rows) {
      // 簡単な更新処理として現在時刻で評価日を更新
      for (const row of rows) {
        await window.aivicApi.update(7, row.リスク評価ID || row.id, {
          評価日: new Date().toISOString(),
          更新日時: new Date().toISOString()
        });
      }
      renderRiskRows(rows);
    }
  });

  // 6. 詳細レポート出力ボタン
  container.querySelector("#btn-export-report").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(7);
    if (!rows) return;

    const csvContent = [
      "リスク評価ID,工程名,リスク種別,リスクレベル,予想遅延日数,対策実施状況,評価日",
      ...rows.map(r => [
        r.リスク評価ID || r.id,
        r.工程名 || "基礎工事",
        r.リスク種別 || "資材調達遅延",
        r.リスクレベル || 15,
        r.予想遅延日数 || 0,
        r.対策実施状況 || "未実施",
        r.評価日 ? new Date(r.評価日).toLocaleDateString() : new Date().toLocaleDateString()
      ].join(","))
    ].join("\n");

    const blob = new Blob(["\uFEFF" + csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "risk_evaluation_report.csv";
    link.click();
  });

  // 7. アラート設定ボタン
  container.querySelector("#btn-alert-settings").addEventListener("click", () => {
    alert("アラート設定画面は今後実装予定です");
  });

  // 8. 発注管理画面への遷移
  container.querySelector("#btn-order-management").addEventListener("click", () => {
    window.showScreen("scr-1780996536358");
  });

  // 9. 行レベル操作のイベントデリゲーション
  container.addEventListener("click", async (e) => {
    const detailBtn = e.target.closest(".detail-btn");
    const editBtn = e.target.closest(".edit-btn");

    if (detailBtn) {
      const id = detailBtn.dataset.id;
      // 詳細表示処理
      alert(`リスク評価ID: ${id} の詳細表示機能は今後実装予定です`);
    }

    if (editBtn) {
      const id = editBtn.dataset.id;
      // 編集処理
      alert(`リスク評価ID: ${id} の編集機能は今後実装予定です`);
    }
  });

  // 10. チャート描画
  function drawSupplierRiskChart() {
    const canvas = container.querySelector("#supplier-risk-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const suppliers = ["A建材", "B鉄鋼", "C木材", "D設備"];
    const riskLevels = [18, 12, 6, 9];
    const colors = ["#ff6b6b", "#ffa726", "#66bb6a", "#ffa726"];

    const barWidth = 40;
    const barSpacing = 20;
    const maxHeight = 150;
    const maxRisk = 20;

    suppliers.forEach((supplier, i) => {
      const x = 30 + i * (barWidth + barSpacing);
      const height = (riskLevels[i] / maxRisk) * maxHeight;
      const y = 170 - height;

      ctx.fillStyle = colors[i];
      ctx.fillRect(x, y, barWidth, height);

      ctx.fillStyle = "#9fb0d1";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(supplier, x + barWidth/2, 190);
      ctx.fillText(riskLevels[i], x + barWidth/2, y - 5);
    });
  }

  function drawDelayPredictionChart() {
    const canvas = container.querySelector("#delay-prediction-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const weeks = ["1週", "2週", "3週", "4週", "5週", "6週"];
    const delays = [2, 3, 5, 4, 6, 3];

    ctx.strokeStyle = "#ff6b6b";
    ctx.lineWidth = 2;
    ctx.beginPath();

    weeks.forEach((week, i) => {
      const x = 50 + i * 60;
      const y = 150 - delays[i] * 20;

      if (i === 0) ctx.moveTo(x, y);
      else ctx.lineTo(x, y);

      ctx.fillStyle = "#ff6b6b";
      ctx.beginPath();
      ctx.arc(x, y, 3, 0, Math.PI * 2);
      ctx.fill();

      ctx.fillStyle = "#9fb0d1";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(week, x, 180);
      ctx.fillText(delays[i] + "日", x, y - 10);
    });

    ctx.strokeStyle = "#ff6b6b";
    ctx.stroke();
  }

  function drawRiskFactorChart() {
    const canvas = container.querySelector("#risk-factor-chart");
    const ctx = canvas.getContext("2d");

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    const factors = ["資材調達", "天候", "人員不足", "設備故障"];
    const percentages = [45, 25, 20, 10];
    const colors = ["#ff6b6b", "#ffa726", "#66bb6a", "#42a5f5"];

    let startAngle = 0;
    const centerX = 150;
    const centerY = 90;
    const radius = 70;

    factors.forEach((factor, i) => {
      const sliceAngle = (percentages[i] / 100) * 2 * Math.PI;

      ctx.fillStyle = colors[i];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius + 20);
      const labelY = centerY + Math.sin(labelAngle) * (radius + 20);

      ctx.fillStyle = "#9fb0d1";
      ctx.font = "10px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(factor, labelX, labelY);
      ctx.fillText(percentages[i] + "%", labelX, labelY + 12);

      startAngle += sliceAngle;
    });
  }

  // チャート初期描画
  setTimeout(() => {
    drawSupplierRiskChart();
    drawDelayPredictionChart();
    drawRiskFactorChart();
  }, 100);
}
